inline std::string envelope_reception_desk(const std::string& body) {
    return "<?xml version=\"1.0\"?>"
           "<soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\">"
           "<soap:Body>" + body + "</soap:Body></soap:Envelope>";
}

// True iff the envelope carries the correct credential for reception_desk. The handler
// gates every operation on this; exposed so it can be unit-tested directly.
inline bool authorized_reception_desk(const ::tinyxml2::XMLDocument& doc) {
    const auto* env = doc.RootElement();                       // soap:Envelope
    const auto* header = ::harpia::soap::detail::find_child(env, "Header");
    const auto* cred = ::harpia::soap::detail::find_child(header, "credentials");
    if (!cred) return false;
    return ::harpia::soap::detail::child_text(cred, "user") == "reception_desk" &&
           ::harpia::soap::detail::child_text(cred, "pswd") == "3ac5d8b36fc7dcfb70888145147ddfb7";
}

inline bool authorized_reception_desk(const std::string& soap_xml) {
    ::tinyxml2::XMLDocument doc;
    if (doc.Parse(soap_xml.c_str()) != ::tinyxml2::XML_SUCCESS) return false;
    return authorized_reception_desk(doc);
}

